import{_ as a,o as t,c as i,a3 as o}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"Projektduplicator 2026","description":"Duplicate and edit EEP model projects with a multilingual interface, ZIP snapshots and manual GitHub updates.","frontmatter":{"title":"Projektduplicator 2026","description":"Duplicate and edit EEP model projects with a multilingual interface, ZIP snapshots and manual GitHub updates."},"headers":[],"relativePath":"en/eep/projektduplicator-2026/index.md","filePath":"en/eep/projektduplicator-2026/index.md","lastUpdated":1792862520000}'),r={name:"en/eep/projektduplicator-2026/index.md"};function n(s,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="projektduplicator-2026" tabindex="-1">Projektduplicator 2026 <a class="header-anchor" href="#projektduplicator-2026" aria-label="Permalink to &quot;Projektduplicator 2026&quot;">​</a></h1><p>Projektduplicator 2026 is UGSo Software’s standalone Windows tool for duplicating and editing EEP model projects. Its interface supports German, English, French and Dutch.</p><h2 id="download-and-launch" tabindex="-1">Download and launch <a class="header-anchor" href="#download-and-launch" aria-label="Permalink to &quot;Download and launch&quot;">​</a></h2><ul><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/download/v4.6.6.59/Projektduplicator-2026-v4.6.6.59-windows.zip" target="_blank" rel="noreferrer">Download Windows ZIP 4.6.6.59</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026/releases/tag/v4.6.6.59" target="_blank" rel="noreferrer">Release, SHA-256 checksum and source</a></li><li><a href="https://github.com/rockbaer2007/projektduplicator-2026" target="_blank" rel="noreferrer">GitHub repository</a></li></ul><p>Extract the entire ZIP to a writable folder and run <code>Projektduplicator_2017.exe</code>. The technical filename is retained for compatibility with existing settings. Windows with .NET Framework 4.8 is required; the solution builds in Visual Studio 2026.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li>Duplicate EEP model projects and edit model information.</li><li>Edit multilingual model names and descriptions and translate them using Google Translate.</li><li>Change the interface language while the application is running.</li><li>Create ZIP snapshots of projects in the configured backup folder.</li><li>Use the existing update buttons to check GitHub releases manually, download and install after confirmation.</li></ul><p>The Google web translator requires internet access and depends on Google’s webpage response format. It does not use an official Google API. Failed translations retain the existing texts.</p><h2 id="settings-and-updates" tabindex="-1">Settings and updates <a class="header-anchor" href="#settings-and-updates" aria-label="Permalink to &quot;Settings and updates&quot;">​</a></h2><p>Back up your projects before making changes. Close editors and save changes to path and spline lists before updating. No update check runs automatically at startup.</p><p>The updater verifies the package and SHA-256 checksum, backs up existing program files and settings, and restarts after installation succeeds. Existing projects, path lists and custom <code>info.txt</code> content are retained. A missing <code>info.txt</code> receives the bundled copy; an existing older copy is intentionally not replaced automatically.</p><h2 id="verified-version" tabindex="-1">Verified version <a class="header-anchor" href="#verified-version" aria-label="Permalink to &quot;Verified version&quot;">​</a></h2><p>Version 4.6.6.59 was approved by the user after local review. The Form1 designer was checked in Visual Studio. The description and credits in <code>info.txt</code> were reviewed in DE/EN/FR/NL. All 49 local checks passed, covering languages, field routing, package validation, data retention, cancellation, rollback and updater process handoff.</p><p>A real public GitHub update with installation and restart still needs a separate test. Existing checks use simulated GitHub responses and temporary installations.</p><h2 id="source-and-notices" tabindex="-1">Source and notices <a class="header-anchor" href="#source-and-notices" aria-label="Permalink to &quot;Source and notices&quot;">​</a></h2><p>UGSo source is MIT licensed; dependencies retain their respective license terms and copyrights. See <code>LICENSE</code> and <code>THIRD-PARTY-NOTICES.md</code> in the repository. EEP and Google Translate belong to their respective rights holders.</p>',16)])])}const f=a(r,[["render",n]]);export{h as __pageData,f as default};
